# shared helpers for the character-style test (runs inside Blender 5.2 on the Mac)
import bpy, os, json, uuid, urllib.request, urllib.parse, time, math
from mathutils import Vector, Matrix
HOME = os.environ.get("AGENT_HOME", os.path.expanduser("~/ShortsRenderAgent"))
ADIR = os.path.join(HOME, "assets"); os.makedirs(ADIR, exist_ok=True)
NOTES = []
UA = {"User-Agent": "blenderkit/3.21.3 (Blender 5.2.3)", "accept": "application/json"}
def get_key():
    for name, ad in bpy.context.preferences.addons.items():
        if "blenderkit" in name.lower():
            return getattr(ad.preferences, "api_key", "") or ""
    return ""
KEY = get_key()

def fetch(url, path, headers=None, timeout=600):
    req = urllib.request.Request(url, headers=headers or {"User-Agent": UA["User-Agent"]})
    with urllib.request.urlopen(req, timeout=timeout) as r, open(path + ".part", "wb") as f:
        while True:
            b = r.read(1 << 20)
            if not b: break
            f.write(b)
    os.replace(path + ".part", path)

def bk_download(aid, durl=None):
    """Blendkit .blend by asset id; durl = files[].downloadUrl from the search (or the asset id itself)."""
    p = os.path.join(ADIR, "bk_" + aid + ".blend")
    if os.path.exists(p) and os.path.getsize(p) > 1000: return p
    durl = durl or ("https://www.blenderkit.com/api/v1/downloads/%s/" % aid)
    errs = []
    for host_url in [durl, durl.replace("www.blenderkit.com", "api.blenderkit.com")]:
        try:
            h = dict(UA); h["Authorization"] = "Bearer " + KEY
            q = host_url + ("&" if "?" in host_url else "?") + urllib.parse.urlencode({"scene_uuid": str(uuid.uuid4())})
            r = urllib.request.urlopen(urllib.request.Request(q, headers=h), timeout=60)
            fp = json.loads(r.read().decode())["filePath"]
            fetch(fp, p)
            return p
        except Exception as e:
            errs.append(type(e).__name__ + ":" + str(getattr(e, "code", ""))[:6])
    NOTES.append("BK dl fail " + aid[:8] + " " + "/".join(errs))
    return None

PH = "https://dl.polyhaven.org/file/ph-assets/"
def ph_tex(name, kind, res="1k"):
    p = os.path.join(ADIR, "ph_%s_%s_%s.jpg" % (name, kind, res))
    if not os.path.exists(p):
        try: fetch(PH + "Textures/jpg/%s/%s/%s_%s_%s.jpg" % (res, name, name, kind, res), p)
        except Exception: NOTES.append("PH " + name + kind); return None
    return p
def ph_hdri(name, res="2k"):
    p = os.path.join(ADIR, "ph_%s_%s.hdr" % (name, res))
    if not os.path.exists(p):
        try: fetch(PH + "HDRIs/hdr/%s/%s_%s.hdr" % (res, name, res), p)
        except Exception: NOTES.append("PH hdri " + name); return None
    return p

def cap_textures(maxpx=2048):
    n = 0
    for im in bpy.data.images:
        try:
            w, h = im.size
            if max(w, h) > maxpx:
                k = maxpx / max(w, h); im.scale(max(1, int(w * k)), max(1, int(h * k))); n += 1
        except Exception: pass
    NOTES.append("tex capped %d" % n)

def sa(o, a, v):
    try: setattr(o, a, v); return True
    except Exception: return False

def eevee_final(sc, samples=16):
    sc.render.engine = "BLENDER_EEVEE"
    ee = sc.eevee
    sa(ee, "taa_render_samples", samples)
    sa(ee, "use_raytracing", True)
    try:
        ee.ray_tracing_options.resolution_scale = "2"; ee.ray_tracing_options.use_denoise = True
    except Exception: pass
    sa(ee, "use_shadows", True); sa(ee, "shadow_ray_count", 1); sa(ee, "shadow_step_count", 4)
    sa(ee, "use_fast_gi", True); sa(ee, "fast_gi_method", "GLOBAL_ILLUMINATION")
    sa(ee, "use_volumetric_shadows", False)
    sa(sc.render, "use_motion_blur", True); sa(sc.render, "motion_blur_shutter", 0.45)
    sa(sc.view_settings, "view_transform", "AgX")
    for lk in ["AgX - Medium High Contrast", "Medium High Contrast"]:
        if sa(sc.view_settings, "look", lk): break
    sc.render.resolution_x, sc.render.resolution_y = 1080, 1920
    sc.render.resolution_percentage = 100
    sa(sc.render, "use_persistent_data", True)
    sc.render.film_transparent = False

SKIP_NAMES = ("wgt", "cs_", "widget", "shape_", "gizmo")
def load_char(path, coll_name="CHAR"):
    """append a character .blend; returns (objs, armature). Skips cameras, lights, widget shapes and non-render helpers."""
    with bpy.data.libraries.load(path, link=False) as (df, dt):
        dt.objects = list(df.objects)
    coll = bpy.data.collections.new(coll_name); bpy.context.scene.collection.children.link(coll)
    objs = []
    for o in dt.objects:
        if o is None or o.type in ("CAMERA", "LIGHT", "LIGHT_PROBE"): continue
        if any(o.name.lower().startswith(s) for s in SKIP_NAMES): continue
        if o.hide_render and o.type != "ARMATURE": continue
        coll.objects.link(o); objs.append(o)
    bpy.context.view_layer.update()
    arms = [o for o in objs if o.type == "ARMATURE"]
    # the armature that actually deforms the meshes
    use = {}
    for o in objs:
        for m in getattr(o, "modifiers", []):
            if m.type == "ARMATURE" and m.object: use[m.object.name] = use.get(m.object.name, 0) + len(o.data.vertices) if o.type == "MESH" else 1
    arm = None
    if use: arm = bpy.data.objects.get(max(use, key=use.get))
    elif arms: arm = max(arms, key=lambda a: len(a.data.bones))
    # non-deforming metarigs etc. never render anyway; keep them hidden
    for a in arms:
        if a is not arm: a.hide_viewport = True
    # giant helper meshes / camera-hidden blockers
    for o in objs:
        if o.type == "MESH" and (not getattr(o, "visible_camera", True)):
            o.hide_render = True; NOTES.append("blocker " + o.name[:20])
    return objs, arm

def strip_drivers(objs):
    nd = 0
    for o in objs:
        for idb in (o, getattr(o, "data", None), getattr(getattr(o, "data", None), "shape_keys", None)):
            ad = getattr(idb, "animation_data", None) if idb is not None else None
            if ad:
                for d in list(ad.drivers):
                    try: bad = (not d.is_valid) or (not d.driver.is_valid)
                    except Exception: bad = True
                    if bad:
                        try: ad.drivers.remove(d); nd += 1
                        except Exception: pass
    return nd

def perf_fix(objs, hair_cap=0.25):
    """BLENDER_PERF style fixes: subdivision capped at 1 render level on deforming meshes, broken drivers removed,
    particle hair children capped, hair curves simplified."""
    ns = nh = 0
    for o in objs:
        for m in getattr(o, "modifiers", []):
            if m.type == "SUBSURF":
                m.levels = 0; m.render_levels = min(m.render_levels, 1); ns += 1
            if m.type == "PARTICLE_SYSTEM":
                ps = m.particle_system.settings
                if ps.type == "HAIR":
                    try:
                        ps.rendered_child_count = max(1, int(ps.rendered_child_count * hair_cap)); ps.child_percent = max(1, int(ps.child_percent * hair_cap)); nh += 1
                    except Exception: pass
    nd = strip_drivers(objs)
    NOTES.append("perf: subsurf %d hair %d drivers %d" % (ns, nh, nd))

def world_bbox(objs):
    mn = Vector((1e9,) * 3); mx = Vector((-1e9,) * 3)
    dg = bpy.context.evaluated_depsgraph_get()
    for o in objs:
        if o.type != "MESH" or o.hide_render: continue
        oe = o.evaluated_get(dg)
        for c in oe.bound_box:
            w = oe.matrix_world @ Vector(c)
            mn = Vector(map(min, mn, w)); mx = Vector(map(max, mx, w))
    return mn, mx

def find_ual_source(path):
    """import the UAL glb (mannequin + all clips) hidden; returns (armature, {action name: action})."""
    before = set(bpy.data.objects); acts0 = set(bpy.data.actions)
    if path.endswith(".fbx"): bpy.ops.import_scene.fbx(filepath=path, automatic_bone_orientation=False)
    else: bpy.ops.import_scene.gltf(filepath=path)
    new = [o for o in bpy.data.objects if o not in before]
    arm = max([o for o in new if o.type == "ARMATURE"], key=lambda a: len(a.data.bones))
    for o in new:
        o.hide_render = True
        if o.type == "MESH": o.hide_viewport = True
    acts = {a.name: a for a in bpy.data.actions if a not in acts0}
    if arm.animation_data:
        for tr in list(arm.animation_data.nla_tracks): arm.animation_data.nla_tracks.remove(tr)
        arm.animation_data.action = None
    return arm, acts, new
EOF_COMMON_PY
cat > retarget.py <<'EOF_RETARGET_PY'
# Generic headless retargeting: transfers animation clips from a source humanoid armature (e.g. Quaternius UAL,
# UE-mannequin names) onto any target humanoid armature (Rigify DEF, Auto-Rig Pro, Mixamo, custom), by copying each
# mapped bone's WORLD rotation change from its rest pose, after aligning the target rest directions to the source
# rest directions (so T-pose vs A-pose rests do not matter). Hips translation is scaled by leg length.
import bpy, re, math
from mathutils import Vector, Matrix, Quaternion

FINGERS = ("thumb", "index", "middle", "ring", "pinky")

def clean(n):
    n = n.lower()
    for p in ("mixamorig:", "mixamorig_", "def-", "def_", "cc_base_", "bip01_", "bip01 ", "b_", "jnt_", "c_"):
        if n.startswith(p): n = n[len(p):]
    return n

def side(n):
    c = n.lower()
    if "left" in c: return "L"
    if "right" in c: return "R"
    if re.search(r"(\.|_|-)l(\.\d+|_\d+)?$", c) or re.search(r"^l(_|\.)", c) or re.search(r"(_|\.)l(_|\.)", c): return "L"
    if re.search(r"(\.|_|-)r(\.\d+|_\d+)?$", c) or re.search(r"^r(_|\.)", c) or re.search(r"(_|\.)r(_|\.)", c): return "R"
    return ""

def role(n):
    """semantic key of a bone name or None. Fingers: 'index1L' etc (segment 1..3)."""
    c = clean(n)
    s = side(n)
    for f in FINGERS:
        if f in c or (f == "pinky" and ("little" in c or "pinkie" in c)):
            m = re.findall(r"(\d+)", c.replace(f, ""))
            seg = int(m[0]) if m else 1
            if seg == 0: seg = 1
            if "meta" in c or "palm" in c: return None
            return ("%s%d%s" % (f, min(seg, 3), s)) if s else None
    if re.match(r"spine\.00[45]$", c): return "neck"
    if c == "spine.006": return "head"
    cx = c.replace("forearm", "fa_rm").replace("fore_arm", "fa_rm")
    if any(k in cx for k in ("toe", "eye", "jaw", "teeth", "tongue", "twist", "breast", "hair", "brow", "lid", "lip", "cheek", "nose", "ear", "roll", "pole", "ik", "tweak", "mch", "org", "socket", "prop", "weapon", "end", "ball", "palm", "root", "corrective", "_bend", "tail", "skirt", "bag")):
        return None
    if re.search(r"fore_?arm|lower_?arm|lowerarm|elbow", c): r = "fa"
    elif re.search(r"upper_?arm|^arm|leftarm|rightarm|(^|[^a-z])arm([^a-z]|$)", c) and "fore" not in c: r = "ua"
    elif re.search(r"shoulder|clavicle|collar", c): r = "sh"
    elif re.search(r"hand|wrist", c): r = "hd"
    elif re.search(r"thigh|up_?leg|upper_?leg|upleg", c): r = "th"
    elif re.search(r"shin|calf|lower_?leg|knee|(^|[^a-z])leg([^a-z]|$)|leftleg|rightleg", c): r = "sn"
    elif re.search(r"foot|ankle", c): r = "ft"
    elif re.search(r"neck", c): return "neck"
    elif re.search(r"head", c): return "head"
    elif re.search(r"hips|pelvis", c) and not s: return "hips"
    elif re.search(r"spine|chest|torso|abdomen|^back", c) and not s: return "spine"
    else: return None
    return r + s if s else None

def order_bones(arm):
    out = []
    def rec(b):
        out.append(b.name)
        for c in b.children: rec(c)
    for b in arm.data.bones:
        if b.parent is None: rec(b)
    return out

def build_map(arm, deform_only=True):
    bones = arm.data.bones
    order = order_bones(arm)
    has_def = any(n.lower().startswith("def-") for n in order)
    m = {}; spines = []
    for n in order:
        if has_def and not n.lower().startswith("def-"): continue
        if deform_only and not has_def and not bones[n].use_deform: continue
        r = role(n)
        if r is None: continue
        if r == "spine": spines.append(n); continue
        if r not in m: m[r] = n
    if "hips" not in m and spines:   # rigify: DEF-spine is the pelvis bone
        m["hips"] = spines.pop(0)
    return m, spines

def side_sign(arm, m):
    """+1 when the character's left side (L bones) is at world +X (character faces -Y)."""
    for k in ("uaL", "thL", "hdL"):
        kr = k[:-1] + "R"
        if k in m and kr in m:
            a = arm.matrix_world @ arm.data.bones[m[k]].head_local
            b = arm.matrix_world @ arm.data.bones[m[kr]].head_local
            return 1 if a.x > b.x else -1
    return 1

def rot3(M):
    return M.to_3x3().normalized()

class Retarget:
    def __init__(self, src, tgt, notes=None):
        self.src, self.tgt = src, tgt
        self.notes = notes if notes is not None else []
        self.smap, self.ssp = build_map(src, deform_only=False)
        self.tmap, self.tsp = build_map(tgt)
        keys = [k for k in self.tmap if k in self.smap]
        self.pairs = {self.tmap[k]: self.smap[k] for k in keys}
        # spines: distribute target spine bones over source spine bones (neck/head handled by keys)
        if self.tsp and self.ssp:
            for i, tn in enumerate(self.tsp):
                j = round(i * (len(self.ssp) - 1) / max(1, len(self.tsp) - 1)) if len(self.tsp) > 1 else len(self.ssp) - 1
                self.pairs[tn] = self.ssp[j]
        self.notes.append("retarget pairs %d (keys %d, spines t%d/s%d); missing in src: %s" % (
            len(self.pairs), len(keys), len(self.tsp), len(self.ssp), ",".join(sorted(k for k in self.tmap if k not in self.smap))[:200]))
        Ms = src.matrix_world; Mt = tgt.matrix_world
        self.Rs_rest = {n: rot3(Ms @ b.matrix_local) for n, b in ((b.name, b) for b in src.data.bones)}
        self.Rt_rest = {b.name: rot3(Mt @ b.matrix_local) for b in tgt.data.bones}
        self.align = {}
        for tn, sn in self.pairs.items():
            ty = self.Rt_rest[tn].col[1]; sy = self.Rs_rest[sn].col[1]
            self.align[tn] = ty.rotation_difference(sy).to_matrix()
        # hips
        self.s_hips = self.smap.get("hips"); self.t_hips = self.tmap.get("hips")
        sh = (Ms @ src.data.bones[self.s_hips].head_local) if self.s_hips else Vector((0, 0, 1))
        th = (Mt @ tgt.data.bones[self.t_hips].head_local) if self.t_hips else Vector((0, 0, 1))
        self.s_hips_rest = sh; self.t_hips_rest = th
        self.hscale = (th.z - Mt.translation.z) / max(1e-4, sh.z - Ms.translation.z)  # floors at the armature origins
        self.t_order = order_bones(tgt)
        self.tpar = {b.name: (b.parent.name if b.parent else None) for b in tgt.data.bones}
        self.tloc = {b.name: b.matrix_local.copy() for b in tgt.data.bones}
        self.Mt_rot_inv = rot3(Mt).inverted()
        sc = Mt.to_scale(); self.tscale = (sc.x + sc.y + sc.z) / 3

    def prepare_target(self):
        """mute everything that would fight FK keys: constraints, drivers, existing action; plain bones (no B-bone noodles)."""
        t = self.tgt; nc = nd = nb = 0
        for pb in t.pose.bones:
            for c in pb.constraints:
                if c.enabled: c.enabled = False; nc += 1
            pb.rotation_mode = "QUATERNION"
            pb.location = (0, 0, 0); pb.rotation_quaternion = (1, 0, 0, 0); pb.scale = (1, 1, 1)
        if t.animation_data:
            t.animation_data.action = None
            for d in list(t.animation_data.drivers):
                try: t.animation_data.drivers.remove(d); nd += 1
                except Exception: pass
        for b in t.data.bones:
            if b.bbone_segments > 1: b.bbone_segments = 1; nb += 1
        self.notes.append("target prep: constraints off %d, drivers %d, bbones %d" % (nc, nd, nb))

    def sample(self, action, frame):
        """source world rotation deltas per source bone name + hips world offset for one clip frame."""
        s = self.src
        s.animation_data_create()
        if s.animation_data.action != action:
            for tr in list(s.animation_data.nla_tracks): s.animation_data.nla_tracks.remove(tr)
            s.animation_data.action = action
            try:
                ad = s.animation_data
                if ad.action_slot is None or ad.action_slot.target_id_type not in ("OBJECT", "UNSPECIFIED"):
                    cands = [sl for sl in action.slots if sl.target_id_type in ("OBJECT", "UNSPECIFIED")]
                    best = next((sl for sl in cands if sl.name_display == s.name), cands[0] if cands else None)
                    if best is not None: ad.action_slot = best
            except Exception as e:
                self.notes.append("slot " + str(e)[:60])
        sc = bpy.context.scene
        fi = int(math.floor(frame)); sc.frame_set(fi, subframe=frame - fi)
        dg = bpy.context.evaluated_depsgraph_get()
        se = s.evaluated_get(dg)
        Ms = se.matrix_world
        need = set(self.pairs.values()) | ({self.s_hips} if self.s_hips else set())
        D = {}
        for n in need:
            pb = se.pose.bones[n]
            W = rot3(Ms @ pb.matrix)
            D[n] = (W @ self.Rs_rest[n].inverted()).to_quaternion()
        off = Vector((0, 0, 0))
        if self.s_hips:
            hp = Ms @ se.pose.bones[self.s_hips].head
            off = hp - self.s_hips_rest
        return D, off

    def solve(self, D, off, extra=None):
        """target basis quaternions (+hips location) from a (possibly blended) source sample.
        extra: {target bone name: Quaternion} additional WORLD-space rotation applied on top (procedural acting)."""
        P = {}; out = {}
        for n in self.t_order:
            par = self.tpar[n]
            rest = self.tloc[n]
            P0 = rest.copy() if par is None else P[par] @ (self.tloc[par].inverted() @ rest)
            sn = self.pairs.get(n)
            if sn is None and not (extra and n in extra):
                P[n] = P0; continue
            if sn is not None:
                Rw = D[sn].to_matrix() @ self.align[n] @ self.Rt_rest[n]
            else:
                Rw = rot3(self.tgt.matrix_world) @ P0.to_3x3().normalized()
            if extra and n in extra:
                Rw = extra[n].to_matrix() @ Rw
            Ra = self.Mt_rot_inv @ Rw
            t = P0.translation.copy()
            if n == self.t_hips:
                t = t + (self.Mt_rot_inv @ (off * self.hscale)) / self.tscale
            des = Matrix.Translation(t) @ Ra.to_4x4()
            basis = P0.inverted() @ des
            P[n] = des
            out[n] = (basis.to_quaternion(), basis.translation.copy() if n == self.t_hips else None)
        return out

    def key(self, out, frame):
        pbs = self.tgt.pose.bones
        for n, (q, loc) in out.items():
            pb = pbs[n]
            pb.rotation_quaternion = q
            pb.keyframe_insert("rotation_quaternion", frame=frame)
            if loc is not None:
                pb.location = loc; pb.keyframe_insert("location", frame=frame)

def blend_samples(a, b, k):
    Da, oa = a; Db, ob = b
    D = {n: Da[n].slerp(Db[n], k) for n in Da}
    return D, oa.lerp(ob, k)
EOF_RETARGET_PY
cat > cand.py <<'EOF_CAND_PY'
# Candidate check for one Blendkit character: download, inspect (rig, face shape keys, hair, polys, textures),
# retarget one Quaternius UAL clip frame onto it, render body (final EEVEE 1080x1920, timed) + two face close-ups.
# Run: Blender -b -P cand.py -- TAG ASSET_ID DOWNLOAD_URL OUTDIR UAL_GLB
import bpy, sys, os, time, json, re, math
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import common as CM
import retarget as RT
from mathutils import Vector, Matrix, Quaternion, Euler
argv = sys.argv[sys.argv.index("--") + 1:]
TAG, AID, DURL, OUT, UAL = argv[:5]
os.makedirs(OUT, exist_ok=True)
INFO = {"tag": TAG, "id": AID}
T0 = time.time()
for o in list(bpy.data.objects): bpy.data.objects.remove(o, do_unlink=True)
sc = bpy.context.scene
CM.eevee_final(sc, int(os.environ.get("CAND_SAMPLES", "16")))
if os.environ.get("CAND_ENGINE"): sc.render.engine = os.environ["CAND_ENGINE"]
# studio
w = bpy.data.worlds.new("W"); sc.world = w; w.use_nodes = True
bg = w.node_tree.nodes.get("Background"); bg.inputs["Color"].default_value = (0.35, 0.37, 0.4, 1); bg.inputs["Strength"].default_value = 0.5
fl = bpy.data.meshes.new("floor"); fl.from_pydata([(-20, -20, 0), (20, -20, 0), (20, 20, 0), (-20, 20, 0)], [], [(0, 1, 2, 3)])
flo = bpy.data.objects.new("floor", fl); sc.collection.objects.link(flo)
fm = bpy.data.materials.new("floorm"); fm.use_nodes = True; fm.node_tree.nodes["Principled BSDF"].inputs["Base Color"].default_value = (0.5, 0.48, 0.46, 1); fl.materials.append(fm)
def light(name, kind, loc, energy, col, size, tgt):
    ld = bpy.data.lights.new(name, kind); ld.energy = energy; ld.color = col
    if kind == "AREA": ld.size = size
    o = bpy.data.objects.new(name, ld); o.location = loc; sc.collection.objects.link(o)
    d = Vector(tgt) - o.location; o.rotation_euler = d.to_track_quat("-Z", "Y").to_euler(); return o
light("key", "AREA", (-1.6, -2.2, 2.6), 600, (1, 0.9, 0.8), 1.5, (0, 0, 1.2))
light("fill", "AREA", (2.0, -2.0, 1.5), 180, (0.8, 0.88, 1.0), 2.0, (0, 0, 1.0))
light("rim", "AREA", (0.8, 2.2, 2.4), 400, (0.9, 0.95, 1.0), 1.0, (0, 0, 1.3))

p = CM.bk_download(AID, DURL)
INFO["download_s"] = round(time.time() - T0, 1)
if not p:
